function normHex(h){
  h=String(h||'').trim().replace(/^#/,'');
  if(/^[0-9a-fA-F]{3}$/.test(h)){ h=h.split('').map(function(c){return c+c;}).join(''); }
  if(/^[0-9a-fA-F]{6}$/.test(h)) return '#'+h.toLowerCase();
  return null;
}
function hexToRgb(h){ var n=parseInt(h.slice(1),16); return {r:(n>>16)&255, g:(n>>8)&255, b:n&255}; }
function relLum(c){ function f(x){ x/=255; return x<=0.03928? x/12.92 : Math.pow((x+0.055)/1.055,2.4); }
  return 0.2126*f(c.r)+0.7152*f(c.g)+0.0722*f(c.b); }
function contrastRatio(a,b){ var la=relLum(a), lb=relLum(b); var hi=Math.max(la,lb), lo=Math.min(la,lb);
  return Math.round((hi+0.05)/(lo+0.05)*100)/100; }
function parseColors(text){
  text=String(text||'');
  var toks=text.split(/[\s,;，；]+/).map(function(s){return s.trim();}).filter(function(s){return s.length;});
  var colors=[], invalid=[], seen={};
  toks.forEach(function(t){ var h=normHex(t);
    if(h){ if(!seen[h]){ seen[h]=1; colors.push(h); } }
    else if(t) invalid.push(t);
  });
  return {colors:colors, invalid:invalid};
}
function levelFor(r){ if(r>=7) return 'AAA'; if(r>=4.5) return 'AA'; if(r>=3) return 'AA Large'; return 'Fail'; }
function auditPalette(text){
  var p=parseColors(text); var cols=p.colors;
  if(cols.length<2) return {error:'至少需要 2 个有效颜色', colors:cols, invalid:p.invalid};
  var pairs=[], worst=99, best=0;
  for(var i=0;i<cols.length;i++){ for(var j=i+1;j<cols.length;j++){
    var r=contrastRatio(hexToRgb(cols[i]), hexToRgb(cols[j]));
    worst=Math.min(worst,r); best=Math.max(best,r);
    pairs.push({a:cols[i], b:cols[j], ratio:r, level:levelFor(r), aa:r>=4.5, aaa:r>=7}); } }
  var total=pairs.length, aaCount=pairs.filter(function(x){return x.aa;}).length,
      aaaCount=pairs.filter(function(x){return x.aaa;}).length;
  pairs.sort(function(x,y){return x.ratio-y.ratio;});
  var score=Math.round(aaCount/total*100);
  return {colors:cols, invalid:p.invalid, pairs:pairs, total:total, aaCount:aaCount,
          aaaCount:aaaCount, worst:worst, best:best, score:score};
}
var EXPORTS={normHex:normHex, hexToRgb:hexToRgb, contrastRatio:contrastRatio,
             parseColors:parseColors, auditPalette:auditPalette, levelFor:levelFor};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ColorPaletteAuditForgePure = EXPORTS; }
